// Spektronautilus offline support (generated by build.py: the version and the file list are filled in at build time).
// Every file of the site is stored on the first visit. Pages then start from the stored copy, with or without internet.
// A new version is stored in the background and only takes over when the visitor chooses (or when all tabs are closed).
const VERSION = '__VERSION__', CACHE = 'spk-' + VERSION, FILES = __FILES__;
self.addEventListener('install', e => {
  e.waitUntil((async () => { const c = await caches.open(CACHE); await c.addAll(FILES.map(f => new Request(f, { cache: 'reload' }))); })());
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => { for (const k of await caches.keys()) if (k.startsWith('spk-') && k !== CACHE) await caches.delete(k); await self.clients.claim(); })());
});
self.addEventListener('message', e => { if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting(); });
self.addEventListener('fetch', e => {
  const r = e.request; if (r.method !== 'GET') return;
  const u = new URL(r.url); if (u.origin !== location.origin || u.pathname.includes('/api/')) return;
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = await c.match(r, { ignoreSearch: true }); if (hit) return hit;
    try {
      const n = await fetch(r);
      if (n.ok && n.status === 200) c.put(r, n.clone()).catch(() => {});          // things that are fetched later (like the video engine) are stored when first used
      return n;
    } catch (err) {
      if (r.mode === 'navigate') { const f = await c.match('./index.html'); if (f) return f; }
      return new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
    }
  })());
});
